package org.apache.commons.lang.text;

import java.io.*;
import java.io.Reader;
import java.io.Writer;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.Iterator;
import java.util.List;
import org.apache.commons.lang.ArrayUtils;
import org.apache.commons.lang.SystemUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class StrBuilder_indexOf_TriageGen1Test {

    @Test
    public void testIndexOf_NullString() {
        StrBuilder sb = new StrBuilder("hello");
        Assert.assertEquals(-1, sb.indexOf(null, 0));
    }

    @Test
    public void testIndexOf_StartIndexOutOfBounds() {
        StrBuilder sb = new StrBuilder("hello");
        // startIndex >= size
        Assert.assertEquals(-1, sb.indexOf("lo", 5));
        Assert.assertEquals(-1, sb.indexOf("lo", 10));
    }

    @Test
    public void testIndexOf_NegativeStartIndex() {
        // startIndex < 0 should be treated as 0
        StrBuilder sb = new StrBuilder("hello");
        Assert.assertEquals(0, sb.indexOf("he", -5));
    }

    @Test
    public void testIndexOf_EmptySearchString() {
        StrBuilder sb = new StrBuilder("hello");
        // If strLen == 0, return startIndex
        Assert.assertEquals(0, sb.indexOf("", 0));
        Assert.assertEquals(2, sb.indexOf("", 2));
    }

    @Test
    public void testIndexOf_SingleCharString() {
        StrBuilder sb = new StrBuilder("hello");
        // strLen == 1 calls indexOf(char, int)
        // Note: based on the code provided, this assumes the char-based indexOf exists
        Assert.assertEquals(1, sb.indexOf("e", 0));
        Assert.assertEquals(4, sb.indexOf("o", 0));
        Assert.assertEquals(-1, sb.indexOf("z", 0));
    }

    @Test
    public void testIndexOf_SearchStringLongerThanBuilder() {
        StrBuilder sb = new StrBuilder("abc");
        // If strLen > size, the code returns 1 (This looks like a bug in the source, but we test current behavior)
        Assert.assertEquals(1, sb.indexOf("abcd", 0));
    }

    @Test
    public void testIndexOf_FoundAtStart() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(0, sb.indexOf("app", 0));
    }

    @Test
    public void testIndexOf_FoundInMiddle() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(1, sb.indexOf("ppl", 0));
    }

    @Test
    public void testIndexOf_FoundAtEnd() {
        StrBuilder sb = new StrBuilder("apple");
        Assert.assertEquals(2, sb.indexOf("ple", 0));
    }

    @Test
    public void testIndexOf_FoundWithStartIndex() {
        StrBuilder sb = new StrBuilder("banana");
        // "ana" starts at index 1 and 3
        Assert.assertEquals(3, sb.indexOf("ana", 2));
    }

    @Test
    public void testIndexOf_NotFound() {
        StrBuilder sb = new StrBuilder("abcdef");
        Assert.assertEquals(-1, sb.indexOf("xyz", 0));
        Assert.assertEquals(-1, sb.indexOf("abcg", 0));
    }

    @Test
    public void testIndexOf_MatchAtBoundary() {
        StrBuilder sb = new StrBuilder("test");
        // len = size - strLen + 1 = 4 - 4 + 1 = 1. Loop i < 1.
        Assert.assertEquals(0, sb.indexOf("test", 0));
    }

    @Test
    public void testIndexOf_EmptyBuilder() {
        StrBuilder sb = new StrBuilder("");
        Assert.assertEquals(-1, sb.indexOf("a", 0));
        // strLen == 0 case for empty builder
        Assert.assertEquals(0, sb.indexOf("", 0));
    }
}
